{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, count(*) n, approx_quantile(duration/1e6,0.05) p05, approx_quantile(duration/1e6,0.25) p25, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.75) p75, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client' UNION ALL SELECT 'no', count(*), approx_quantile(duration/1e6,0.05), approx_quantile(duration/1e6,0.25), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.75), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client'",
          "claim": "search's client calls to rate.Rate/GetRates rose from a p50 of about 0.7 ms to about 2.2 s, with most calls 1.9–2.5 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE service_name='rate' AND span_name='rate.Rate/GetRates' GROUP BY ALL UNION ALL SELECT 'no', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='rate' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "rate's own server span stays sub-millisecond (p50 about 0.8 ms), so the added time is on the wire before rate handles the request."
        },
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, duration d, epoch_ms(time) t FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, duration d, epoch_ms(time) t FROM abnormal_traces WHERE service_name='rate' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Server') SELECT count(*) n, approx_quantile((s.t-c.t),0.5) start_gap_ms_p50, approx_quantile((c.t+c.d/1e6)-(s.t+s.d/1e6),0.5) end_gap_ms_p50, approx_quantile(c.d/1e6,0.5) client_ms, approx_quantile(s.d/1e6,0.5) server_ms FROM c JOIN s ON c.trace_id=s.trace_id AND c.span_id=s.parent_span_id",
          "claim": "Matched pairs: rate's server span starts about 1.9 s after search's client span starts; response leg adds only about 0.17 s."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, service_name, span_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client') GROUP BY ALL UNION ALL SELECT 'no', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client') GROUP BY ALL",
          "claim": "search.Search/Nearby server time rose from about 1.4 ms to about 2.2 s, tracking the delayed rate calls."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, service_name, span_name, attr_span_kind k, count(*) n, approx_quantile(duration/1e6,0.5) p50, approx_quantile(duration/1e6,0.95) p95 FROM abnormal_traces WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client') GROUP BY ALL UNION ALL SELECT 'no', service_name, span_name, attr_span_kind, count(*), approx_quantile(duration/1e6,0.5), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client') GROUP BY ALL",
          "claim": "User-facing frontend HTTP /hotels p50 rose from about 7 ms to about 2.3 s, matching the delayed search call."
        }
      ]
    }
  ]
}
